const imgUrl = "https://www.realclipart.com/png/middle/281-2810601_simple-cartoon-mouse-cartoon-mouse.png";

// Open the direct image in a new tab
const newTab = await tool.tabs_create({ url: imgUrl });
const imgTabId = newTab.details.tabId;
await tool.wait_for({ tabId: imgTabId, condition: "load_state", value: "load", timeout_ms: 10000 });

// Now let's test if the image actually has transparent pixels
const transparencyCheck = await browserjs(imgTabId, () => {
  const img = document.querySelector('img');
  if (!img) return { error: "No img element" };

  const canvas = document.createElement('canvas');
  canvas.width = img.naturalWidth || img.width;
  canvas.height = img.naturalHeight || img.height;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0);

  // Check corner pixels (e.g. 0,0 and 5,5) and edge pixels for alpha < 255
  const p1 = ctx.getImageData(0, 0, 1, 1).data;
  const p2 = ctx.getImageData(5, 5, 1, 1).data;
  const p3 = ctx.getImageData(canvas.width - 5, 5, 1, 1).data;

  // Also count some transparent pixels
  let transparentCount = 0;
  const sampleData = ctx.getImageData(0, 0, Math.min(100, canvas.width), Math.min(100, canvas.height)).data;
  for (let i = 3; i < sampleData.length; i += 4) {
    if (sampleData[i] < 250) transparentCount++;
  }

  return {
    width: canvas.width,
    height: canvas.height,
    p1: Array.from(p1),
    p2: Array.from(p2),
    p3: Array.from(p3),
    sampleTransparentRatio: transparentCount / (sampleData.length / 4)
  };
});

console.log("Image tab ID:", imgTabId);
console.log("Transparency check:", transparencyCheck);

