const tabId = 825319348;

const svgInput = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="100" height="100">
  <polygon points="10,80 90,80 80,30 20,40" fill="#FFA500"/>
  <circle cx="40" cy="65" r="8" fill="#FF8C00"/>
  <circle cx="70" cy="70" r="6" fill="#FF8C00"/>
  <circle cx="50" cy="45" r="5" fill="#FF8C00"/>
</svg>`;

// Set value in the input Ace editor and trigger update
const result = await browserjs(tabId, (svg) => {
  const inputEl = document.getElementById('input');
  const editor = (window.ace && window.ace.edit(inputEl)) || inputEl.env?.editor;
  if (editor) {
    editor.setValue(svg, -1);
    return { set: true, val: editor.getValue() };
  }
  return { set: false };
}, svgInput);

console.log("Input set result:", result);

// Wait for compilation/update
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });

// Now read the output editor value
const outputVal = await browserjs(tabId, () => {
  const outputEl = document.getElementById('output');
  const editor = (window.ace && window.ace.edit(outputEl)) || outputEl.env?.editor;
  return editor ? editor.getValue() : outputEl.innerText;
});

console.log("SVGR Output:\n", outputVal);

